  type: 'product',
  filter: {
    hidden: true,
    variants: false,
    draft: false,
    archived: false,
  },
});

const selected = await resourcePicker({
  type: 'product',
  filter: {
    query: 'Sweater',
  },
});

const selected = await resourcePicker({type: 'product'});

if (selected) {
